/** BatchRequest contains multiple items for batch processing. */
export interface BatchRequest {
requestId: string;
items: SmallMessage[];
headers: Map<string, string>;
submittedAt: Timestamp;
timeout?: Duration;
priority: Priority;
}

/** Encodes a BatchRequest to the writer. */
export function encodeBatchRequest(writer: Writer, msg: BatchRequest): void {

  // Field 1: request_id
  if (msg.requestId !== undefined && msg.requestId !== null && msg.requestId.length > 0) {
    writer.writeTag(1, WireType.Bytes);
    writer.writeString(msg.requestId);
  }

  // Field 2: items
  if (msg.items !== undefined && msg.items !== null && msg.items.length > 0) {
    writer.writeTag(2, WireType.Bytes);
    writeArray(writer, msg.items, (w, v) => { encodeSmallMessage(w, v) });
  }

  // Field 3: headers
  writer.writeTag(3, WireType.Bytes);
  writeMap(writer, msg.headers, (w, k) => { w.writeString(k) }, (w, v) => { w.writeString(v) });

  // Field 4: submitted_at
  writer.writeTag(4, WireType.Bytes);
  { const __cp = writer.beginMessage(); encodeTimestamp(writer, msg.submittedAt); writer.endMessage(__cp); };

  // Field 5: timeout
  if (msg.timeout !== undefined && msg.timeout !== null) {
    writer.writeTag(5, WireType.Bytes);
    { const __cp = writer.beginMessage(); encodeDuration(writer, msg.timeout); writer.endMessage(__cp); };
  }

  // Field 6: priority
  writer.writeTag(6, WireType.SVarint);
  writer.writeSVarint(msg.priority);
// End marker
  writer.writeEndMarker();
}

/** Decodes a BatchRequest from the reader. */
export function decodeBatchRequest(reader: Reader): BatchRequest {
  // Initialize all fields up front so V8 builds a single stable
  // hidden class. The previous Partial-and-fill pattern produced a
  // different hidden-class transition tree per input ordering, which
  // deopted downstream consumers.
  const result: BatchRequest = {
    requestId: '',
    items: [],
    headers: new Map(),
    submittedAt: ({} as Timestamp),
    timeout: ({} as Duration),
    priority: 0 as Priority,
  };

  while (true) {
    const { fieldNumber, wireType } = reader.readTag();
    if (fieldNumber === 0) break; // End marker

    switch (fieldNumber) {
      case 1:
        result.requestId = reader.readString();
        break;
      case 2:
        result.items = readArray(reader, (r) => decodeSmallMessage(r));
        break;
      case 3:
        result.headers = readMap(reader, (r) => r.readString(), (r) => r.readString());
        break;
      case 4:
        result.submittedAt = (() => { reader.enterNested(); try { const __data = reader.readLengthPrefixedBytes(); return decodeTimestamp(new Reader(__data, { limits: reader.getLimits(), validateUtf8: reader.getValidateUtf8() })); } finally { reader.exitNested(); } })();
        break;
      case 5:
        result.timeout = (() => { reader.enterNested(); try { const __data = reader.readLengthPrefixedBytes(); return decodeDuration(new Reader(__data, { limits: reader.getLimits(), validateUtf8: reader.getValidateUtf8() })); } finally { reader.exitNested(); } })();
        break;
      case 6:
        result.priority = reader.readSVarint();
        break;
      default:
        reader.skipValue(wireType);
    }
  }

  return result;
}

/** Marshals a BatchRequest to bytes. */
export function marshalBatchRequest(msg: BatchRequest): Uint8Array {
  const writer = new Writer();
  encodeBatchRequest(writer, msg);
  return writer.bytes();
}

/** Unmarshals a BatchRequest from bytes. */
export function unmarshalBatchRequest(data: Uint8Array, opts?: ReaderOptions): BatchRequest {
  const reader = new Reader(data, opts);
  return decodeBatchRequest(reader);
}

